<div class="page-head"><div><span class="eyebrow dark"><?= e(tr('فروش و پرداخت‌ها','Sales and payments')) ?></span><h1><?= e(tr('صورتحساب‌ها','Invoices')) ?></h1><p><?= fa_digits($total) ?> <?= e(tr('فاکتور، جمع کل','invoices, total')) ?> <?= money($grandTotal) ?></p></div><a class="button ghost" href="<?= e(url('report')) ?>">↗ <?= e(tr('گزارش مالی','Financial report')) ?></a></div>
<form method="get" class="filter-bar"><input type="hidden" name="r" value="invoices"><label class="search-box"><span>⌕</span><input name="q" value="<?= e($search) ?>" placeholder="<?= e(tr('شماره فاکتور یا نام کاربری...','Invoice number or username...')) ?>"></label><select name="status"><option value=""><?= e(tr('همه وضعیت‌ها','All statuses')) ?></option><?php foreach(['unpaid','paid','overdue','cancelled','credited'] as $s):?><option value="<?= e($s) ?>" <?= $status===$s?'selected':'' ?>><?= e(status_text($s)) ?></option><?php endforeach;?></select><button class="button ghost"><?= e(tr('فیلتر','Filter')) ?></button></form>
<section class="panel"><div class="table-wrap"><table><thead><tr><th><?= e(tr('شماره','Number')) ?></th><th><?= e(tr('کاربر','User')) ?></th><th><?= e(tr('پلن','Plan')) ?></th><th><?= e(tr('مبلغ کل','Total')) ?></th><th><?= e(tr('مانده','Balance')) ?></th><th><?= e(tr('وضعیت','Status')) ?></th><th><?= e(tr('سررسید','Due date')) ?></th></tr></thead><tbody><?php foreach($invoices as $invoice):?><tr><td><a href="<?= e(url('invoice-detail',['id'=>$invoice['id']])) ?>" dir="ltr"><strong><?= e($invoice['invoice_number']) ?></strong></a></td><td dir="ltr"><?= e($invoice['username']) ?></td><td><?= e($invoice['plan_name']?:'—') ?></td><td><?= money($invoice['total'],$invoice['currency']?:'IRR') ?></td><td><?= money(max(0,$invoice['total']-$invoice['paid_amount']),$invoice['currency']?:'IRR') ?></td><td><span class="badge <?= badge_class($invoice['status']) ?>"><?= e(status_text($invoice['status'])) ?></span></td><td><?= e($invoice['due_date']) ?></td></tr><?php endforeach;?><?php if(!$invoices):?><tr><td colspan="7" class="empty"><?= e(tr('فاکتوری پیدا نشد.','No invoices found.')) ?></td></tr><?php endif;?></tbody></table></div><?php $pages=(int)ceil($total/$perPage);if($pages>1):?><nav class="pagination"><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++):?><a class="<?= $i===$page?'active':'' ?>" href="<?= e(url('invoices',['page'=>$i,'q'=>$search,'status'=>$status])) ?>"><?= fa_digits($i) ?></a><?php endfor;?></nav><?php endif;?></section>

